// Registers the service worker generated by vite-plugin-pwa.
// Runs in the browser only. Returns an object with `update` and `onNeedRefresh`
// so the app can show an update toast and let the user decide when to reload.

import { registerSW } from "virtual:pwa-register";

let updateSW = null;

export function initServiceWorker({ onNeedRefresh, onOfflineReady } = {}) {
  if (typeof window === "undefined") return null;

  updateSW = registerSW({
    immediate: true,
    onNeedRefresh() {
      if (typeof onNeedRefresh === "function") onNeedRefresh();
    },
    onOfflineReady() {
      if (typeof onOfflineReady === "function") onOfflineReady();
    },
    onRegisterError(error) {
      console.error("Service worker registration failed:", error);
    },
  });

  return updateSW;
}

// Apply a pending update and reload. Safe to call before initServiceWorker;
// it returns silently if there is nothing to update.
export function applyUpdate() {
  if (typeof updateSW === "function") {
    updateSW(true);
  }
}
